<?php defined('ABSPATH') || exit;$d=$args['data'];$lens=$d['lens'];if(!$lens['standouts'])return; ?>
<section id="property-lens" class="dossier-lens dossier-section" aria-labelledby="lens-heading">
 <div class="dossier-section-heading"><p class="dossier-eyebrow">01 / ASPIRE LENS</p><div><h2 id="lens-heading">Read the property<br><em>beyond the listing.</em></h2><p>Key property facts, what they may mean for your decision, and the details worth confirming before you move forward.</p></div></div>
 <h3 class="dossier-small-label">WHAT STANDS OUT</h3>
 <div class="dossier-insights"><?php foreach($lens['standouts'] as $i=>$fact): ?><article><div class="dossier-insight-meta"><span><?php echo esc_html($fact['group']); ?></span><span>0<?php echo $i+1; ?></span></div><?php $value_parts=explode(' · ',$fact['value'],2); ?><h3><?php echo esc_html($value_parts[0]); ?></h3><?php if(isset($value_parts[1])): ?><p class="dossier-value-context"><?php echo esc_html($value_parts[1]); ?></p><?php endif; ?><p class="dossier-fact-label"><?php echo esc_html($fact['label']); ?></p><p class="dossier-implication"><?php echo esc_html($fact['implication']); ?></p></article><?php endforeach; ?></div>
 <?php if($lens['groups']): ?><div class="dossier-lens-groups"><?php foreach($lens['groups'] as $label=>$facts): ?><section><h3><?php echo esc_html($label); ?></h3><dl><?php foreach($facts as $fact): ?><div><dt><?php echo esc_html($fact['label']); ?></dt><dd><?php echo esc_html($fact['value']); ?></dd></div><?php endforeach; ?></dl></section><?php endforeach; ?></div><?php endif; ?>
